\begin{align*}
G(u) & = \begin{bmatrix}
v_G\\
M^{-1}f_G\\
\end{bmatrix} \\
H(u) & = \begin{bmatrix}
v_H\\
M^{-1}f_H\\
\end{bmatrix} \\
v_G & = U_s {U_s}^T M v \\
v_H & = v - v_G \\
f_G & = M U_s {U_s}^T f \\
f_H & = f - f_G \\
\intertext{where} 
U_s & : \mathbb{R}^{ n \times s } \\
M & : \mathbb{R}^{ n \times n } \\
v & : \mathbb{R}^{ n} \\
f & : \mathbb{R}^{ n} \\
K & : \mathbb{R}^{ n \times n } \\
\\
J_G & = \begin{bmatrix}
0 & U_s {U_s}^T M\\
-U_s {U_s}^T K U_s {U_s}^T M & 0\\
\end{bmatrix} \\
J_H & = \begin{bmatrix}
0 & I_{ n }\\
-M^{-1}K & 0\\
\end{bmatrix} - J_G \\
u_+ & = u + \left( \boldsymbol{I} - h J_H \right)^{-1}\left( h H(u) + h \begin{bmatrix}
U_s & 0\\
0 & U_s\\
\end{bmatrix} φ_1\left( h J_G^r \right) G^r(u) \right) \\
\intertext{where} 
\boldsymbol{I} & : \mathbb{R}^{ 2 n \times 2 n } \\
h & : \mathbb{R} \\
φ_1 & : \mathbb{R}^{ k \times k }\rightarrow \mathbb{R}^{ k \times k } \\
u & : \mathbb{R}^{ 2 n \times 1 } \\
\\
J_G^r & = \begin{bmatrix}
0 & I_{ s }\\
-{U_s}^T K U_s & 0\\
\end{bmatrix} \\
G^r(u) & = \begin{bmatrix}
{U_s}^T M v\\
{U_s}^T f\\
\end{bmatrix} \\
\end{align*}
\end{minipage}
}
