function output = heartlib(U_s, M, v, f, K, boldsymbolI, h, phi_1, u)
% output = heartlib(`$U_s$`, M, v, f, K, `$\boldsymbol{I}$`, h, `$φ_1$`, u)
%
%    `$G(u)$` = [`$v_G$`
%              M⁻¹`$f_G$`]
%    `$H(u)$` = [`$v_H$`
%              M⁻¹`$f_H$`]
%    `$v_G$` = `$U_s$``$U_s$`^T Mv
%    `$v_H$` =  v - `$v_G$`
%    `$f_G$` =  M`$U_s$``$U_s$`^T f
%    `$f_H$` =  f - `$f_G$`
%    
%    where 
%    `$U_s$` : ℝ^(n × s)
%    M : ℝ^(n × n)
%    v : ℝ^n
%    f : ℝ^n
%    K : ℝ^(n × n)
%    
%    `$J_G$` = [0    `$U_s$``$U_s$`^TM
%          -`$U_s$``$U_s$`^TK`$U_s$``$U_s$`^TM 0 ]
%    `$J_H$` =  [0     I_n
%                -M⁻¹K 0] - `$J_G$` 
%    
%    
%    `$u_+$` =  u + (`$\boldsymbol{I}$` -h`$J_H$`)⁻¹(h `$H(u)$` + h[`$U_s$` 0
%                                                   0   `$U_s$`] `$φ_1$`(h`$J_G^r$`) `$G^r(u)$`)
%    where 
%    `$\boldsymbol{I}$` : ℝ^(2n × 2n)
%    h : ℝ
%    `$φ_1$` : ℝ^(k×k) -> ℝ^(k×k)
%    u : ℝ^(2n × 1)
%    
%    `$J_G^r$` = [0     I_s
%                -`$U_s$`^TK`$U_s$` 0]
%    `$G^r(u)$` = [`$U_s$`^TMv
%                `$U_s$`^Tf]
%    
%    
    v = reshape(v,[],1);
    f = reshape(f,[],1);

    n = size(U_s, 1);
    s = size(U_s, 2);
    assert( isequal(size(U_s), [n, s]) );
    assert( isequal(size(M), [n, n]) );
    assert( numel(v) == n );
    assert( numel(f) == n );
    assert( isequal(size(K), [n, n]) );
    assert( isequal(size(boldsymbolI), [2*n, 2*n]) );
    assert(numel(h) == 1);
    assert( isequal(size(u), [2*n, 1]) );
    assert( mod(2*n, 1) == 0.0 );
    assert( mod(2*n, 1) == 0.0 );
    assert( mod(2*n, 1) == 0.0 );

    % `$v_G$` = `$U_s$``$U_s$`^T Mv

    v_G = U_s * U_s' * M * v;
    % `$v_H$` =  v - `$v_G$`

    v_H = v - v_G;
    % `$f_G$` =  M`$U_s$``$U_s$`^T f

    f_G = M * U_s * U_s' * f;
    % `$G(u)$` = [`$v_G$`
    %           M⁻¹`$f_G$`]

    Gu_0 = [[reshape(v_G, [n, 1])]; [reshape(((M)\(f_G)), [n, 1])]];
    Gu = Gu_0;
    % `$f_H$` =  f - `$f_G$`

    f_H = f - f_G;
    % `$H(u)$` = [`$v_H$`
    %           M⁻¹`$f_H$`]

    Hu_0 = [[reshape(v_H, [n, 1])]; [reshape(((M)\(f_H)), [n, 1])]];
    Hu = Hu_0;
    % `$J_G$` = [0    `$U_s$``$U_s$`^TM
    %       -`$U_s$``$U_s$`^TK`$U_s$``$U_s$`^TM 0 ]

    J_G_0 = [[zeros(n, n), U_s * U_s' * M]; [-U_s * U_s' * K * U_s * U_s' * M, zeros(n, n)]];
    J_G = J_G_0;
    % `$J_H$` =  [0     I_n
    %             -M⁻¹K 0] - `$J_G$`

    J_H_0 = [[zeros(n, n), speye(n)]; [-((M)\(K)), zeros(n, n)]];
    J_H = J_H_0 - J_G;
    % `$J_G^r$` = [0     I_s
    %             -`$U_s$`^TK`$U_s$` 0]

    J_G_r_0 = [[zeros(s, s), speye(s)]; [-U_s' * K * U_s, zeros(s, s)]];
    J_G_r = J_G_r_0;
    % `$G^r(u)$` = [`$U_s$`^TMv
    %             `$U_s$`^Tf]

    G_ru_0 = [[reshape(U_s' * M * v, [s, 1])]; [reshape(U_s' * f, [s, 1])]];
    G_ru = G_ru_0;
    % `$u_+$` =  u + (`$\boldsymbol{I}$` -h`$J_H$`)⁻¹(h `$H(u)$` + h[`$U_s$` 0
    %                                                0   `$U_s$`] `$φ_1$`(h`$J_G^r$`) `$G^r(u)$`)

    u_plus_sign_2 = [[U_s, zeros(n, s)]; [zeros(n, s), U_s]];
    u_plus_sign = u + (((boldsymbolI - h * J_H))\((h * Hu + h * u_plus_sign_2 * phi_1(h * J_G_r) * G_ru)));
    output.Gu = Gu;
    output.Hu = Hu;
    output.v_G = v_G;
    output.v_H = v_H;
    output.f_G = f_G;
    output.f_H = f_H;
    output.J_G = J_G;
    output.J_H = J_H;
    output.u_plus_sign = u_plus_sign;
    output.J_G_r = J_G_r;
    output.G_ru = G_ru;
end

